{
        // Arrange
        var channel = new AnalogChannel(0, 65535)
        {
            PortRange = 1.0,
            CalibrationM = 2.0,
            CalibrationB = 1.0,
            InternalScaleM = 1.0
        };

        // Act
        var result = channel.GetScaledValue(65535); // Max value

        // Assert
        // Expected: (65535 / 65535) * 1.0 * 2.0 + 1.0 = 3.0
        Assert.Equal(3.0, result, precision: 6);
